typedef struct { const char *name, *cups; double width, height; } Envelope;
static const Envelope formats[] = {{"DL (220 x 110 mm)", "EnvDL", 220, 110}, {"C6 (162 x 114 mm)", "EnvC6", 162, 114}, {"C5 (229 x 162 mm)", "EnvC5", 229, 162}, {"C4 (324 x 229 mm)", "EnvC4", 324, 229}};
typedef struct { GtkWidget *sender, *recipient, *printer, *preview; GtkComboBoxText *format; GtkAdjustment *rx,*ry,*sx,*sy,*rf,*sf; GtkToggleButton *sender_on; GtkSpinButton *copies; } App;
static const Envelope *selected_format(App *a) { int i=gtk_combo_box_get_active(GTK_COMBO_BOX(a->format)); return (i>=0 && i<(int)(sizeof formats/sizeof formats[0])) ? &formats[i] : &formats[0]; }
static gchar *cfg_path(void) { const char *h=g_get_home_dir(); return g_build_filename(h, CFG_DIR+1, CFG_NAME+1, NULL); }
static gchar *json_escape(const gchar *s) { GString *o=g_string_new("\""); for(;*s;s++){ if(*s=='\\'||*s=='\"')g_string_append_c(o,'\\'); if(*s=='\n')g_string_append(o,"\\n"); else if(*s=='\r')g_string_append(o,"\\r"); else g_string_append_c(o,*s); } g_string_append_c(o,'\"'); return g_string_free(o,FALSE); }
static gchar *text(GtkWidget *w) { GtkTextBuffer *b=gtk_text_view_get_buffer(GTK_TEXT_VIEW(w)); GtkTextIter a,z; gtk_text_buffer_get_bounds(b,&a,&z); return gtk_text_buffer_get_text(b,&a,&z,FALSE); }
static void set_text(GtkWidget *w,const gchar *s) { gtk_text_buffer_set_text(gtk_text_view_get_buffer(GTK_TEXT_VIEW(w)),s?s:"",-1); }
static gchar *json_string(const gchar *data,const gchar *key) { gchar *p=g_strstr_len(data,-1,key); if(!p)return g_strdup(""); p=strchr(p,':'); if(!p)return g_strdup(""); p=strchr(p,'\"'); if(!p)return g_strdup(""); p++; GString *o=g_string_new(""); int esc=0; for(;*p;p++){ if(esc){ if(*p=='n')g_string_append_c(o,'\n'); else g_string_append_c(o,*p); esc=0; } else if(*p=='\\')esc=1; else if(*p=='\"')break; else g_string_append_c(o,*p); } return g_string_free(o,FALSE); }
static double json_num(const gchar *d,const gchar *key,double def) { gchar *p=g_strstr_len(d,-1,key); if(!p)return def; p=strchr(p,':'); return p?g_ascii_strtod(p+1,NULL):def; }
static gboolean json_bool(const gchar *d,const gchar *key,gboolean def) { gchar *p=g_strstr_len(d,-1,key); if(!p)return def; p=strchr(p,':'); return p && g_str_has_prefix(g_strstrip(p+1),"true"); }
static void load_config(App *a) { gchar *path=cfg_path(),*d=NULL; if(g_file_get_contents(path,&d,NULL,NULL)){ gchar *s=json_string(d,"\"sender\""); set_text(a->sender,s); g_free(s); s=json_string(d,"\"recipient\""); set_text(a->recipient,s); g_free(s); s=json_string(d,"\"format\""); for(int i=0;i<4;i++)if(!strcmp(s,formats[i].cups))gtk_combo_box_set_active(GTK_COMBO_BOX(a->format),i); g_free(s); gtk_adjustment_set_value(a->rx,json_num(d,"\"recipient_x\"",110)); gtk_adjustment_set_value(a->ry,json_num(d,"\"recipient_y\"",45)); gtk_adjustment_set_value(a->sx,json_num(d,"\"sender_x\"",15)); gtk_adjustment_set_value(a->sy,json_num(d,"\"sender_y\"",12)); gtk_adjustment_set_value(a->rf,json_num(d,"\"font_size\"",11)); gtk_adjustment_set_value(a->sf,json_num(d,"\"sender_font_size\"",8)); gtk_toggle_button_set_active(a->sender_on,json_bool(d,"\"sender_enabled\"",TRUE)); } g_free(d); g_free(path); }
static void save_config(App *a) { gchar *path=cfg_path(),*dir=g_path_get_dirname(path),*s=json_escape(text(a->sender)),*r=json_escape(text(a->recipient)),*p=gtk_combo_box_text_get_active_text(GTK_COMBO_BOX_TEXT(a->printer)),*f=json_escape(selected_format(a)->cups); gchar *d=g_strdup_printf("{\n  \"sender\": %s,\n  \"recipient\": %s,\n  \"sender_enabled\": %s,\n  \"format\": %s,\n  \"font_size\": %.2f,\n  \"sender_font_size\": %.2f,\n  \"recipient_x\": %.2f,\n  \"recipient_y\": %.2f,\n  \"sender_x\": %.2f,\n  \"sender_y\": %.2f,\n  \"printer\": %s\n}\n",s,r,gtk_toggle_button_get_active(a->sender_on)?"true":"false",f,gtk_adjustment_get_value(a->rf),gtk_adjustment_get_value(a->sf),gtk_adjustment_get_value(a->rx),gtk_adjustment_get_value(a->ry),gtk_adjustment_get_value(a->sx),gtk_adjustment_get_value(a->sy),p?json_escape(p):"\"\""); g_mkdir_with_parents(dir,0700); g_file_set_contents(path,d,-1,NULL); g_free(path);g_free(dir);g_free(s);g_free(r);g_free(p);g_free(f);g_free(d); }
static void draw_addr(cairo_t *c,const gchar *s,double x,double y,double pt,double scale) { if(!s||!*s)return; PangoLayout *l=pango_cairo_create_layout(c); PangoFontDescription *f=pango_font_description_from_string("DejaVu Sans"); pango_font_description_set_absolute_size(f,pt*scale*PANGO_SCALE); pango_layout_set_font_description(l,f); pango_layout_set_text(l,s,-1); cairo_move_to(c,x*MM*scale,(y*MM+pt/72*25.4)*scale); pango_cairo_show_layout(c,l); pango_font_description_free(f);g_object_unref(l); }
static void draw_preview_addr(cairo_t *c,const gchar *s,double ox,double oy,double x,double y,double pt,double scale) { if(!s||!*s)return; PangoLayout *l=pango_cairo_create_layout(c); PangoFontDescription *f=pango_font_description_from_string("DejaVu Sans"); double px=pt/72.0*25.4*scale; pango_font_description_set_absolute_size(f,px*PANGO_SCALE); pango_layout_set_font_description(l,f); pango_layout_set_text(l,s,-1); cairo_move_to(c,ox+x*scale,oy+(y+pt/72*25.4)*scale); pango_cairo_show_layout(c,l); pango_font_description_free(f);g_object_unref(l); }
static gboolean preview(GtkWidget *w,cairo_t *c,gpointer data) { App *a=data; const Envelope *e=selected_format(a); int ww=gtk_widget_get_allocated_width(w),hh=gtk_widget_get_allocated_height(w); double scale=fmin((ww-20)/e->width,(hh-20)/e->height), x=(ww-e->width*scale)/2,y=(hh-e->height*scale)/2; cairo_set_source_rgb(c,1,1,1);cairo_paint(c);cairo_set_source_rgb(c,.15,.15,.15);cairo_rectangle(c,x,y,e->width*scale,e->height*scale);cairo_stroke(c); gchar *r=text(a->recipient),*s=text(a->sender); if(gtk_toggle_button_get_active(a->sender_on))draw_preview_addr(c,s,x,y,gtk_adjustment_get_value(a->sx),gtk_adjustment_get_value(a->sy),gtk_adjustment_get_value(a->sf),scale); draw_preview_addr(c,r,x,y,gtk_adjustment_get_value(a->rx),gtk_adjustment_get_value(a->ry),gtk_adjustment_get_value(a->rf),scale);g_free(r);g_free(s); return FALSE; }
static void changed(GtkWidget *w,gpointer d){ gtk_widget_queue_draw(((App*)d)->preview); }
static void error_msg(GtkWindow *p,const gchar *s){ GtkWidget *m=gtk_message_dialog_new(p,GTK_DIALOG_MODAL,GTK_MESSAGE_ERROR,GTK_BUTTONS_CLOSE,"%s",s);gtk_dialog_run(GTK_DIALOG(m));gtk_widget_destroy(m); }
static gboolean make_pdf(App *a,const gchar *file) { const Envelope *e=selected_format(a); gchar *r=text(a->recipient),*s=text(a->sender); if(!g_strstrip(r)[0]){g_free(r);g_free(s);return FALSE;} cairo_surface_t *surf=cairo_pdf_surface_create(file,e->width*MM,e->height*MM); cairo_t *c=cairo_create(surf); cairo_set_source_rgb(c,1,1,1);cairo_paint(c);cairo_set_source_rgb(c,0,0,0); if(gtk_toggle_button_get_active(a->sender_on))draw_addr(c,s,gtk_adjustment_get_value(a->sx),gtk_adjustment_get_value(a->sy),gtk_adjustment_get_value(a->sf),1); draw_addr(c,r,gtk_adjustment_get_value(a->rx),gtk_adjustment_get_value(a->ry),gtk_adjustment_get_value(a->rf),1);cairo_destroy(c);cairo_surface_destroy(surf);g_free(r);g_free(s);return TRUE; }
static void save_pdf(GtkButton *b,gpointer data){App*a=data;GtkWidget*d=gtk_file_chooser_dialog_new("PDF speichern",GTK_WINDOW(gtk_widget_get_toplevel(GTK_WIDGET(b))),GTK_FILE_CHOOSER_ACTION_SAVE,"Abbrechen",GTK_RESPONSE_CANCEL,"Speichern",GTK_RESPONSE_ACCEPT,NULL);gtk_file_chooser_set_current_name(GTK_FILE_CHOOSER(d),"umschlag.pdf");if(gtk_dialog_run(GTK_DIALOG(d))==GTK_RESPONSE_ACCEPT){gchar*p=gtk_file_chooser_get_filename(GTK_FILE_CHOOSER(d));if(!make_pdf(a,p))error_msg(GTK_WINDOW(d),"Empfängeradresse fehlt.");else save_config(a);g_free(p);}gtk_widget_destroy(d);}
static void printers(GtkButton *button,gpointer data){(void)button;App*a=data;GError*e=NULL;gchar*out=NULL;g_spawn_command_line_sync("lpstat -e",&out,NULL,NULL,&e);gtk_combo_box_text_remove_all(GTK_COMBO_BOX_TEXT(a->printer));if(out){gchar**v=g_strsplit(out,"\n",-1);for(int i=0;v[i];i++)if(*v[i])gtk_combo_box_text_append_text(GTK_COMBO_BOX_TEXT(a->printer),v[i]);g_strfreev(v);}if(e){error_msg(GTK_WINDOW(gtk_widget_get_toplevel(a->printer)),"CUPS/lpstat nicht erreichbar.");g_error_free(e);}g_free(out);}
static void print_pdf(GtkButton*b,gpointer data){App*a=data;const Envelope *e=selected_format(a);gchar*tmp=g_strdup("/tmp/dl-umschlag-XXXXXX");int fd=g_mkstemp(tmp);if(fd>=0)close(fd);else{g_free(tmp);return;}if(!make_pdf(a,tmp)){unlink(tmp);g_free(tmp);error_msg(GTK_WINDOW(gtk_widget_get_toplevel(GTK_WIDGET(b))),"Empfängeradresse fehlt.");return;}gchar*p=gtk_combo_box_text_get_active_text(GTK_COMBO_BOX_TEXT(a->printer));if(!p||!*p){unlink(tmp);g_free(tmp);g_free(p);error_msg(GTK_WINDOW(gtk_widget_get_toplevel(GTK_WIDGET(b))),"Kein Drucker ausgewählt.");return;}gchar copies[12];g_snprintf(copies,sizeof copies,"%d",gtk_spin_button_get_value_as_int(a->copies));gchar pageopt[64];g_snprintf(pageopt,sizeof pageopt,"PageSize=%s",e->cups);gchar*argv[]={"lp","-d",p,"-n",copies,"-o",pageopt,"-o","InputSlot=ByPassTray","-o","MediaType=Envelope","-o","print-scaling=none","-o","sides=one-sided",tmp,NULL};gchar*out=NULL,*err=NULL;GError*e2=NULL;gint status=0;g_spawn_sync(NULL,argv,NULL,G_SPAWN_SEARCH_PATH,NULL,NULL,&out,&err,&status,&e2);unlink(tmp);if(e2||status){error_msg(GTK_WINDOW(gtk_widget_get_toplevel(GTK_WIDGET(b))),err&&*err?err:"CUPS hat Auftrag abgelehnt.");if(e2)g_error_free(e2);}else{save_config(a);GtkWidget*m=gtk_message_dialog_new(GTK_WINDOW(gtk_widget_get_toplevel(GTK_WIDGET(b))),GTK_DIALOG_MODAL,GTK_MESSAGE_INFO,GTK_BUTTONS_OK,"Druckauftrag an CUPS übergeben. Physischer Druck nicht bestätigt.");gtk_dialog_run(GTK_DIALOG(m));gtk_widget_destroy(m);}g_free(out);g_free(err);g_free(p);g_free(tmp);}
static void clear_fields(GtkButton*b,gpointer d){App*a=d;set_text(a->sender,"");set_text(a->recipient,"");changed(NULL,a);}
